sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.campus-event-card {
    background: #ffffff;
    border: 1px solid #d9d9d9;
    border-radius: 18px;
    padding: 20px;
    margin-bottom: 18px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
    transition: 0.2s;
}

.campus-event-card:hover {
    box-shadow: 0 5px 18px rgba(0,0,0,0.12);
}

.event-header {
    display: flex;
    align-items: flex-start;
    gap: 15px;
}

.event-logo {
    width: 70px;
    height: 70px;
    border: 1px solid #ddd;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 32px;
    flex-shrink: 0;
}

.event-title-section {
    flex: 1;
}

.event-title-section h3 {
    margin: 0 0 10px 0;
    font-size: 22px;
    font-weight: 600;
    color: #172b4d;
}

.event-meta {
    display: flex;
    gap: 18px;
    color: #555;
    font-size: 14px;
}

.event-location {
    display: flex;
    gap: 8px;
    margin-top: 15px;
    color: #444;
    font-size: 14px;
    line-height: 1.5;
}

.location-icon {
    font-size: 17px;
}

.event-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 18px;
}

.event-tag {
    background: #f5f5f5;
    border-radius: 18px;
    padding: 8px 13px;
    font-size: 13px;
    color: #333;
}

.event-bottom {
    display: flex;
    justify-content: space-between;
    margin-top: 20px;
    color: #555;
    font-size: 14px;
}

.event-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 18px;
    padding-top: 15px;
    border-top: 1px solid #eeeeee;
}

.verified-badge {
    color: #18864b;
    font-weight: 600;
    font-size: 13px;
}

.event-actions {
    font-size: 22px;
    color: #333;
}

.no-matches {
    padding: 25px;
    text-align: center;
    background: #ffffff;
    border-radius: 15px;
    border: 1px solid #ddd;
}

.no-matches h4 {
    margin-bottom: 8px;
}

sp_widget.script:
(function() {

    data.matches = [];

    // Get the current logged-in student's profile
    var profile = new GlideRecord('x_snc_campus_con_0_student_profile');
    profile.addQuery('student', gs.getUserID());
    profile.query();

    if (!profile.next()) {
        return;
    }

    var studentSkills = (profile.getValue('skills') || '').toLowerCase();
    var studentInterests = (profile.getValue('interests') || '').toLowerCase();

    // Get only verified events
    var events = new GlideRecord('x_snc_campus_con_0_events');
    events.addQuery('verification_status', 'verified');
    events.query();

    while (events.next()) {

        var technologyTags =
            (events.getValue('technology_tags') || '').toLowerCase();

        var matched = false;

        // Match Skills with Technology Tags
        if (studentSkills && technologyTags) {

            if (technologyTags.indexOf(studentSkills) !== -1 ||
                studentSkills.indexOf(technologyTags) !== -1) {

                matched = true;
            }
        }

        // Match Interests with Technology Tags
        if (!matched && studentInterests && technologyTags) {

            if (technologyTags.indexOf(studentInterests) !== -1 ||
                studentInterests.indexOf(technologyTags) !== -1) {

                matched = true;
            }
        }

        // Add matching event
        if (matched) {

            var daysLeft = -1;

            // Calculate days remaining until registration deadline
            var deadline = events.getValue('registration_deadline');

            if (deadline) {

                var deadlineDate = new GlideDateTime(deadline);
                var today = new GlideDateTime();

                var difference =
                    GlideDateTime.subtract(today, deadlineDate);

                daysLeft =
                    Math.floor(
                        difference.getNumericValue() /
                        (1000 * 60 * 60 * 24)
                    );
            }

            data.matches.push({

                name: events.getValue('event_name'),

                date: events.getValue('event_date'),

                technology: events.getValue('technology_tags'),

                location: events.getValue('location'),

                fees: events.getValue('fees'),

                eventType: events.getValue('event_type'),

                organizer: events.getDisplayValue('organizer'),

                deadline: events.getValue('registration_deadline'),

                daysLeft: daysLeft

            });
        }
    }

})();
